INSERT INTO tasks (id, user_id, project_id, title, description, status, priority, due_date, next_action, source) VALUES
('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', '11111111-1111-1111-1111-111111111111', '22222222-2222-2222-2222-222222222222', 'Fix moisture sensor calibration', 'Current readings are 15% off compared to reference meter. Need to recalibrate in controlled environment.', 'blocked', 1, NOW() + INTERVAL '1 day', 'Buy reference moisture meter', 'manual'),
('bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb', '11111111-1111-1111-1111-111111111111', '22222222-2222-2222-2222-222222222222', 'Design 3D printed enclosure', 'Design waterproof housing for Arduino and sensors. Must allow sensor probes to extend.', 'todo', 2, NOW() + INTERVAL '3 days', 'Open Fusion 360 and sketch initial design', 'manual'),
('cccccccc-cccc-cccc-cccc-cccccccccccc', '11111111-1111-1111-1111-111111111111', '22222222-2222-2222-2222-222222222222', 'Write Arduino firmware v0.2', 'Implement sleep mode to reduce power consumption. Add BLE notification support.', 'in_progress', 2, NOW() + INTERVAL '5 days', 'Research Arduino LowPower library', 'manual'),
('dddddddd-dddd-dddd-dddd-dddddddddddd', '11111111-1111-1111-1111-111111111111', '33333333-3333-3333-3333-333333333333', 'Follow up with TechCorp recruiter', 'Sent application 5 days ago. No response yet. Follow up email needed.', 'todo', 1, NOW() + INTERVAL '1 day', 'Draft follow-up email referencing specific role requirements', 'manual'),
('eeeeeeee-eeee-eeee-eeee-eeeeeeeeeeee', '11111111-1111-1111-1111-111111111111', '33333333-3333-3333-3333-333333333333', 'Update resume with recent project', 'Add Garden Guardian project to resume. Highlight IoT, embedded C, and 3D design skills.', 'todo', 2, NOW() + INTERVAL '2 days', 'Write 3 bullet points for resume', 'manual'),
('ffffffff-ffff-ffff-ffff-ffffffffffff', '11111111-1111-1111-1111-111111111111', '44444444-4444-4444-4444-444444444444', 'Complete heat exchanger calculations', 'Need to finish thermal efficiency calculations for shell-and-tube design. Missing fouling factor data.', 'in_progress', 1, NOW() + INTERVAL '2 days', 'Find fouling factor reference table in textbook', 'manual'),
('00000001-0000-0000-0000-000000000001', '11111111-1111-1111-1111-111111111111', '44444444-4444-4444-4444-444444444444', 'Review lecture notes week 8-10', 'Missed week 9 lecture. Need to catch up on entropy and exergy analysis before final.', 'todo', 2, NOW() + INTERVAL '4 days', 'Email classmate for week 9 notes', 'manual'),
('00000002-0000-0000-0000-000000000002', '11111111-1111-1111-1111-111111111111', '55555555-5555-5555-5555-555555555555', 'Summarize Deep Work book', 'Read Cal Newport''s Deep Work. Extract key concepts for productivity system.', 'todo', 3, NOW() + INTERVAL '7 days', 'Create structured notes with actionable takeaways', 'manual');
INSERT INTO memories (id, user_id, project_id, memory_type, title, content, summary, source, importance, confidence) VALUES
('00000003-0000-0000-0000-000000000003', '11111111-1111-1111-1111-111111111111', '22222222-2222-2222-2222-222222222222', 'decision', 'Chose DHT22 over DHT11', 'Selected DHT22 temperature/humidity sensor instead of DHT11 for better accuracy (±0.5°C vs ±2°C) and wider range. Cost difference was $3 vs $1.50 but accuracy is critical for plant health monitoring.', 'Chose DHT22 for better accuracy despite higher cost', 'engineering_agent', 4, 0.95),
('00000004-0000-0000-0000-000000000004', '11111111-1111-1111-1111-111111111111', '22222222-2222-2222-2222-222222222222', 'failure', 'Capacitive sensor corrosion', 'Capacitive soil moisture sensor corroded after 2 weeks in high-humidity environment. The PCB traces near the probe area oxidized. Need to use conformal coating or switch to fully sealed sensor design.', 'Capacitive sensor corroded in humid environment - needs sealing', 'user', 5, 1.0),
('00000005-0000-0000-0000-000000000005', '11111111-1111-1111-1111-111111111111', '33333333-3333-3333-3333-333333333333', 'preference', 'Resume style preference', 'User prefers concise 1-page resumes with project-focused bullet points. Dislikes long paragraphs. Wants metrics in every bullet (%, $, time savings).', 'User prefers 1-page metric-driven resumes', 'system', 3, 0.9),
('00000006-0000-0000-0000-000000000006', '11111111-1111-1111-1111-111111111111', '44444444-4444-4444-4444-444444444444', 'summary', 'Thermodynamics midterm results', 'Scored 87/100 on midterm. Lost points on: (1) entropy generation in heat exchangers, (2) exergy analysis of turbines. Strong on: first law applications, property tables.', 'Midterm: 87/100. Weak on entropy generation and exergy analysis.', 'user', 4, 1.0),
('00000007-0000-0000-0000-000000000007', '11111111-1111-1111-1111-111111111111', NULL, 'preference', 'Email communication style', 'User prefers short direct emails under 100 words. Hates fluff and formal corporate language. Prefers bullet points for action items. Always wants specific next steps defined.', 'Short direct emails, bullet points, specific next steps', 'system', 3, 0.85);
